def parse_log_line(s):
    if not isinstance(s, str):
        raise TypeError("Input must be a string")

    stripped = s.strip()
    if not stripped:
        raise ValueError("Empty line (whitespace only)")

    parts = stripped.split(' ', 2)
    if len(parts) < 3:
        raise ValueError("Log line must have three fields: TIMESTAMP LEVEL MSG")

    timestamp_str, level, msg = parts[0], parts[1], parts[2] if len(parts) > 2 else ''

    # Validate timestamp ISO8601 format
    try:
        clean_ts = timestamp_str.replace('Z', '+00:00')
        from datetime import datetime
        datetime.fromisoformat(clean_ts)
    except (ValueError, TypeError):
        raise ValueError(f"Invalid ISO8601 timestamp: {timestamp_str}")

    # Validate level
    if level not in ('INFO', 'WARN', 'ERROR'):
        raise ValueError(f"Invalid log level: {level}. Must be one of INFO, WARN, ERROR")

